import fs from 'node:fs';
import assert from 'node:assert/strict';
import {tmpdir} from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawn } from 'node:child_process';
const root=fs.realpathSync(fileURLToPath(new URL('.',import.meta.url))),file=path.join(root,'resources.json');
const manifest=fs.existsSync(file)?JSON.parse(fs.readFileSync(file,'utf8')):{root,processes:[],resources:[]};
if(!fs.existsSync(file))fs.writeFileSync(file,'{}');
const home=path.join(root,'home');fs.mkdirSync(home,{recursive:true});
function record(){const pending=[root],rows=[];while(pending.length){const name=pending.pop(),stat=fs.lstatSync(name,{bigint:true});if(stat.isSymbolicLink())throw new Error('Unexpected task link: '+name);rows.push({file:name,dev:String(stat.dev),ino:String(stat.ino),directory:stat.isDirectory()});if(stat.isDirectory())for(const child of fs.readdirSync(name))pending.push(path.join(name,child));}manifest.resources=rows;fs.writeFileSync(file,JSON.stringify(manifest,null,2));}
assert.equal(fs.realpathSync(tmpdir()),root);
const [label,...args]=process.argv.slice(2);
args.unshift('--import',new URL('./verify-env.mjs',import.meta.url).href); if(!/^[a-z0-9-]+$/.test(label)||!args.length)throw new Error('label and Node arguments required');
const env={PATH:process.env.PATH,SystemRoot:process.env.SystemRoot,WINDIR:process.env.WINDIR,COMSPEC:process.env.COMSPEC,PATHEXT:process.env.PATHEXT,
 TMP:root,TEMP:root,TMPDIR:root,HOME:home,USERPROFILE:home,XDG_CONFIG_HOME:home,SP_CODING_AGENT_DIR:path.join(home,'agent'),SP_CODING_AGENT_SESSION_DIR:path.join(home,'sessions'),SP_OFFLINE:'1',SP_SKIP_VERSION_CHECK:'1',SP_TUI_WRITE_LOG:'',PF_JITI_CACHE_DIR:path.join(root,'jiti-cache'),JITI_FS_CACHE:'false',npm_config_update_notifier:'false'};
const log=fs.openSync(path.join(root,label+'.log'),'wx');
const child=spawn(process.execPath,args,{cwd:path.resolve(root,'../..'),env,windowsHide:true,stdio:['ignore',log,log]});
const owner={label,pid:child.pid,args,started:new Date().toISOString(),settled:false};manifest.processes.push(owner);record();
child.on('error',error=>{owner.error=error.message;});
child.on('close',(code,signal)=>{owner.settled=true;owner.code=code;owner.signal=signal;owner.finished=new Date().toISOString();fs.closeSync(log);record();console.log(JSON.stringify(owner));process.exitCode=code??1;});

import assert from 'node:assert/strict';
import {setImmediate as turn} from 'node:timers/promises';
import {alphaSession} from '../../tests/helpers/alpha-session.ts';
import {alphaMessage} from '../../tests/helpers/alpha-stream.ts';
import {AssistantMessageComponent} from '../../packages/coding-agent/src/modes/interactive/components/assistant-message.ts';
const history=5000,updates=64;
const block='\n## Section 中文 👩‍💻e\u0301\n\n| Key | Value |\n| --- | --- |\n| width | '+ 'value '.repeat(40)+' |\n\n```ts\nconst value = "'+ 'code '.repeat(90)+'";\n```\n\n- '+ 'paragraph '.repeat(70)+'\n';
async function run(mode){
 const messages=Array.from({length:history},(_,i)=>alphaMessage([{type:'text',text:'history '+i+' 中文 '+ 'retained '.repeat(10)}]));
 const f=await alphaSession({mode,messages,sinkDelay:2,customTools:[{name:'pf08_progress',label:'PF08',description:'Offline fixture',parameters:{type:'object',properties:{}},async execute(){return {content:[{type:'text',text:'unused'}]};}}]});
 const message=alphaMessage([{type:'text',text:'start'}]),event={type:'message_update',message,assistantMessageEvent:{type:'text_delta',contentIndex:0,delta:block,partial:message}};
 const weak=[new WeakRef(f.session),new WeakRef(f.runtime),new WeakRef(f.mode),new WeakRef(f.internal.renderer),new WeakRef(f.terminal),new WeakRef(message)];
 let rendered=0,progress=0,widthChanges=0,resizeFallbacks=0;const fallbackRows=[];const began=performance.now();
 try{
  assert.equal(await f.mode.init(),true);await f.internal.loadInitializationHighlightLanguages();
  f.session._emit({type:'message_start',message});f.internal.renderer.renderNow();await f.internal.renderer.flushTerminalFrames();
  const component=f.internal.streamingComponent;assert.ok(component);weak.push(new WeakRef(component));
  f.internal.renderInstrumentation.reset();
  for(let i=0;i<8;i++){message.content[0].text+=' plain';f.session._emit(event);f.internal.renderer.renderNow();await f.internal.renderer.flushTerminalFrames();}
  const stable=f.internal.renderInstrumentation.snapshot();assert.equal(stable.completedItemRenders,0);assert.equal(stable.fullHistoryFallbacks,0);
  f.session._emit({type:'tool_execution_start',toolCallId:'pf08-tool',toolName:'pf08_progress',args:{}});
  f.internal.renderInstrumentation.reset();
  if(mode==='regular'){
   const original=f.internal.renderer.doRender,visible=f.internal.renderer.renderVisibleDocument;let nonResize;
   f.internal.renderer.renderVisibleDocument=function(w,h){
    const previousHeight=this.viewportDocumentHeight??this.previousLines.length,previousStart=this.viewportWindowStart??Math.max(0,previousHeight-h);
    const result=visible.call(this,w,h);if(!result){const m=this.viewportMutationSummary;nonResize={kind:m.kind,heightChanged:m.heightChanged,first:m.earliestChangedLine,last:m.latestChangedLine,previousStart,previousHeight};}return result;
   };
   f.internal.renderer.doRender=function(){
    const resized=(this.previousWidth!==0&&this.previousWidth!==f.terminal.columns)||(this.previousHeight!==0&&this.previousHeight!==f.terminal.rows);
    const before=f.internal.renderInstrumentation.snapshot().fullHistoryFallbacks;
    const result=original.call(this),added=f.internal.renderInstrumentation.snapshot().fullHistoryFallbacks-before;
    if(added){if(resized)resizeFallbacks+=added;fallbackRows.push({resized,added,...(resized?{}:nonResize)});}nonResize=undefined;
    return result;
   };
  }
  for(let i=0;i<updates;i++){
   message.content[0].text+=block;assert.equal(f.session._emit(event),undefined);
   f.session._emit({type:'tool_execution_update',toolCallId:'pf08-tool',toolName:'pf08_progress',args:{},partialResult:{content:[{type:'text',text:'progress '+i+' 中文'}]}});progress++;
   if(i%4===0){f.resizeSource.columns=[80,120,160][widthChanges%3];f.resizeSource.emit('resize');widthChanges++;}
   f.internal.renderer.renderNow();rendered++;await turn();
  }
  f.session._emit({type:'tool_execution_end',toolCallId:'pf08-tool',toolName:'pf08_progress',args:{},result:{content:[{type:'text',text:'PF08 final result'}]},isError:false});
  f.session._emit({type:'message_end',message});await f.internal.handleEvent({type:'agent_end',messages:[message]});
  await f.internal.renderer.flushTerminalFrames();assert.equal(f.internal.streamingMessage,undefined);
  const reference=new AssistantMessageComponent(message);assert.deepEqual(component.render(f.resizeSource.columns),reference.render(f.resizeSource.columns));
  const metrics=f.internal.renderInstrumentation.snapshot(),queue=f.internal.renderer.getTerminalFrameQueueSnapshot();
  for(const key of ['framePromisesCreated','frameAbortControllersCreated','frameWrapperObjectsCreated','fullSizeFrameCopies'])assert.equal(metrics[key],0,key);
  console.log('PF08_FALLBACK_DIAGNOSTIC '+JSON.stringify({mode,resizeFallbacks,fallbackRows}));
  assert.equal(metrics.fullHistoryFallbacks,fallbackRows.reduce((total,row)=>total+row.added,0));
  assert.ok(fallbackRows.every(row=>row.resized||(row.kind==='range'&&row.heightChanged===true)),'Every replay must be resize or the existing non-tail height-change fallback');
  assert.ok(metrics.terminalFrameQueueHighWaterMark<=2);assert.ok(metrics.pendingRenderRequestHighWaterMark<=1);
  assert.equal(queue.activeWrites,0);assert.equal(queue.pendingFrames,0);assert.equal(queue.pendingRenderIntents,0);
  return {weak,row:{mode,history,updates,progress,widthChanges,resizeFallbacks,fallbackRows,renderAttempts:rendered,finalChars:message.content[0].text.length,stableCompletedRenders:stable.completedItemRenders,metrics,queue,elapsedMs:performance.now()-began}};
 }finally{await f.release();}
}
const results=[];
for(const mode of ['regular','fullscreen']){const {weak,row}=await run(mode);for(let i=0;i<6;i++){await turn();global.gc();}row.liveOwners=weak.filter(ref=>ref.deref()!==undefined).length;assert.equal(row.liveOwners,0);results.push(row);}
console.log(JSON.stringify({fixture:'pf08-stream-resize-progress-backpressure',scope:'Real session/UI components and delayed Writable; direct event delivery, synthetic resize source, no provider request or native resize.',results}));

